typedef struct handler { int (*handle)(struct req *); struct handler *next; } handler;

int chain_run(handler *h, struct req *r) {
    for (; h; h = h->next)
        if (h->handle(r) == HANDLED)
            return HANDLED;          /* first taker stops the chain */
    return UNHANDLED;                /* explicit terminal outcome */
}
